formula.en:
# if - elif - else: grade from marks
marks = int(input("Enter marks out of 100: "))
if marks >= 90:
    grade = "A1"
elif marks >= 75:
    grade = "A2"
elif marks >= 60:
    grade = "B"
elif marks >= 33:
    grade = "C"
else:
    grade = "Needs improvement"
print("Grade:", grade)

